with open('contract.txt') as f:
    text = f.read()

# Find sections by regex for ' 2.', ' 3.', etc.
import re
sections = {}
for i in range(1, 10):
    pattern = rf'(?:(?<=\s)|(?<=^)){re.escape(str(i))}\.\s'
    # Actually easier: split by number dot space
    # Let's find the start of each section header like '2. '
    m = re.search(rf'\b{i}\.\s', text)
    if m:
        start = m.start()
        # find start of next section
        next_m = re.search(rf'\b{i+1}\.\s', text[start+1:])
        if next_m:
            end = start + 1 + next_m.start()
        else:
            end = len(text)
        sections[i] = text[start:end]
    else:
        sections[i] = None

for i in [2,3,4,5,6,7]:
    print(f'\n=== SECTION {i} ===\n')
    print(sections[i][:2000] if sections[i] else 'Not found')
