python3 << 'EOF'
with open('contract.txt') as f:
    text = f.read()

keywords = ['limitation', 'cap', 'maximum', 'aggregate', 'not exceed', 'not be liable', 'limitation of liability', 'damages', 'consequential']
for kw in keywords:
    idx = text.lower().find(kw)
    if idx != -1:
        start = max(idx-100, 0)
        end = min(idx+300, len(text))
        print(f"\n--- {kw} ---\n{text[start:end]}")
    else:
        print(f"\n--- {kw} --- NOT FOUND")
